"""Render static pages from approved content. Python standard library only."""
from pathlib import Path
import json, html, re
ROOT=Path(__file__).resolve().parents[1]
DATA=json.loads((ROOT/'content.json').read_text())
E=DATA['event']; P=DATA['problems']; J=DATA['judges']
esc=html.escape
REG=E['registrationUrl'] or '/#registration'

def header(directory=False):
 return f'''<header class="site-header"><a class="brand" href="/" aria-label="ACE Club home"><img src="/assets/ace.jpeg" alt="ACE Club" width="52" height="52"><span>ACE CLUB<small>RAMAIAH INSTITUTE OF TECHNOLOGY</small></span></a><nav aria-label="Main navigation"><a href="/problem-statements/" {'aria-current="page"' if directory else ''}>Problem Statements</a><a href="/#judges">Judges</a><a href="/#faq">FAQ</a><a class="nav-register" href="{REG}" data-register>Register Now <span aria-hidden="true">↗</span></a></nav></header>'''

def footer():return '''<footer class="site-footer"><a class="wordmark" href="/">ACE HACKATHON<span aria-hidden="true">↗</span></a><p>Organized by ACE Club<br>Ramaiah Institute of Technology</p><div class="footer-links"><a href="/credits.html">Visual credits</a><a href="#top">Back to top ↑</a></div></footer>'''

def page(title,body,directory=False,detail=False):
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#05080e"><meta name="description" content="Ace Hackathon by ACE Club, Ramaiah Institute of Technology. 13 November 2026, ESB Seminar Hall. Code. Create. Conquer."><title>{esc(title)} · Ace Hackathon</title><link rel="icon" href="/assets/ace.jpeg"><link rel="stylesheet" href="/styles.css"><script src="/app.js" defer></script><script type="module" src="/scene.js"></script></head><body id="top" class="{'directory' if directory else 'home'} {'detail-page' if detail else ''}"><a class="skip-link" href="#main">Skip to content</a><div class="universe" aria-hidden="true"><canvas id="universe-canvas"></canvas><div class="scene-fallback"></div><div class="scene-shade"></div></div>{header(directory)}{body}{footer()}<a class="floating-register" href="{REG}" data-register hidden>Register Now <span aria-hidden="true">↗</span></a><div class="sr-only" id="announcement" role="status"></div></body></html>'''

def picture(name,alt,cls=''):
 return f'<div class="logo-card {cls}"><div class="logo-safe"><img src="/assets/{name}" alt="{esc(alt)}" loading="lazy"></div><span>{esc(alt)}</span></div>'

def brief_html(p):
 text=p['brief'][p['brief'].index('Problem Description'):]
 out=[]
 for para in re.split(r'\n\s*\n',text):
  para=para.strip()
  if para in ['Problem Description','Problem Statement','Expected Functionalities','Expected Outcome']:out.append('<h2>'+esc(para)+'</h2>')
  elif para.startswith('- '):out.append('<ul>'+''.join('<li>'+esc(line.removeprefix('- '))+'</li>' for line in para.splitlines())+'</ul>')
  else:out.append('<p'+(' class="brief-note"' if para.startswith('Note:') else '')+'>'+esc(para)+'</p>')
 return ''.join(out)

judges=''
for i,j in enumerate(J,1):
 portrait=f'<img src="{esc(j["portrait"])}" alt="{esc(j["name"])}">' if j['portrait'] else f'<span class="portrait-monogram">{j["initials"]}</span><span class="portrait-caption">Official photograph to follow</span>'
 judges+=f'''<article class="judge-card"><div class="judge-portrait">{portrait}<span class="portrait-index">0{i}</span></div><div class="judge-body"><p class="eyebrow">JUDGE 0{i}</p><h3>{esc(j['name'])}</h3><p class="muted">{esc(j['designation'] or 'Designation to be announced')}</p><a class="profile-link" href="{esc(j['linkedin'])}" target="_blank" rel="noopener noreferrer"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M20 3H4a1 1 0 0 0-1 1v16a1 1 0 0 0 1 1h16a1 1 0 0 0 1-1V4a1 1 0 0 0-1-1ZM8 18H5.5v-8H8ZM6.75 9A1.5 1.5 0 1 1 6.75 6a1.5 1.5 0 0 1 0 3ZM18.5 18H16v-4.3c0-2-2.5-1.8-2.5 0V18H11v-8h2.5v1c1.2-1.9 5-2 5 2.8Z"/></svg> LinkedIn <span aria-hidden="true">↗</span><span class="sr-only"> — {esc(j['name'])}, opens in a new tab</span></a></div></article>'''
preview=''.join(f'<a class="preview-row" href="/problem-statements/{p["slug"]}/"><span class="problem-index">{p["id"]}</span><h3>{esc(p["title"])}</h3><span class="row-arrow" aria-hidden="true">↗</span></a>' for p in P)
body=f'''<main id="main"><section class="hero" id="hero"><div class="hero-content"><p class="eyebrow hero-eyebrow">ACE CLUB PRESENTS <span>·</span> 13 NOVEMBER 2026</p><h1><span class="title-ace">ACE</span><span class="title-hackathon">HACKATHON</span></h1><p class="tagline">Code. Create. Conquer.</p><div class="hero-prize"><span class="eyebrow">PRIZE POOL</span><strong>{E['prize']}</strong><span class="prize-note">(with exciting gifts, vouchers and cash prizes)</span></div><div class="hero-actions"><a class="button primary" id="hero-register" href="{REG}" data-register>Register Now <span aria-hidden="true">↗</span></a><a class="hero-secondary" href="/problem-statements/">Explore the challenges <span aria-hidden="true">→</span></a></div><p class="registration-note">{'Registration link coming soon' if not E['registrationUrl'] else ''}</p><p class="hero-meta"><span>13 NOV · 10:00 AM IST</span><span>ESB SEMINAR HALL</span></p></div><div class="hero-bottom"><a href="#affiliations" class="scroll-cue">EXPLORE THE EVENT <span aria-hidden="true">↓</span></a><button class="mission-detail" id="signal" aria-label="Decode the hidden signal" aria-expanded="false"><span class="signal-dots" aria-hidden="true">· · · ━ ━ ━ · · ·</span><span id="signal-message">SIGNAL / AWAITING CONTACT</span></button></div></section>
<section class="section affiliations" id="affiliations"><div class="section-kicker"><span class="eyebrow">01 / A WORLD OF POSSIBILITIES</span><span class="science-note">GRAVITY CONNECTS EVERYTHING</span></div><h2>Ideas without<br>an event horizon.</h2><p class="intro">Real-world problem statements inspired by leading global companies. Bring your perspective to challenges that reach beyond the classroom.</p><div class="affiliation-group"><div class="group-heading"><h3>Problem statements</h3><span>Inspired by</span></div><div class="logo-grid">{picture('hp.svg','HP','hp-logo')}{picture('cisco.svg','Cisco')}{picture('samsung.svg','Samsung')}{picture('jpmorgan.svg','J.P. Morgan','jpm-logo')}{picture('apple.svg','Apple','apple-logo')}</div><p class="affiliation-note">Inspiration references; these companies are not listed as event sponsors or official partners.</p></div><div class="affiliation-group judge-affiliations"><div class="group-heading"><h3>Judges From</h3><a href="#judges">Meet the panel <span aria-hidden="true">↗</span></a></div><p class="muted">Judge affiliations will be announced once confirmed.</p></div><div class="affiliation-group"><div class="group-heading"><h3>Sponsors</h3><span>With the support of</span></div><div class="sponsor-grid">{picture('partex.jpeg','PARTEX','sponsor partex')}{picture('coastal.jpeg','Coastal Naati Kitchen','sponsor coastal')}{picture('tags.png','TAGS','sponsor tags')}</div></div></section>
<section class="section challenge-preview" id="challenges"><div class="preview-intro"><p class="eyebrow">02 / PICK YOUR PERSPECTIVE</p><h2>Real challenges.<br>Remarkable possibilities.</h2><p class="intro">{len(P):02d} published problem statements. Explore the full briefs in a dedicated space built for focus.</p><a class="button primary" href="/problem-statements/">View Problem Statements <span aria-hidden="true">↗</span></a></div><div class="preview-list">{preview}</div></section>
<section class="section judges" id="judges"><div class="section-kicker"><p class="eyebrow">03 / THE PEOPLE BEHIND THE PERSPECTIVE</p><span class="science-note">DIFFERENT MINDS. SHARED CURIOSITY.</span></div><h2>Meet the Judges</h2><div class="judge-grid">{judges}</div></section>
<section class="section faq" id="faq"><div><p class="eyebrow">04 / BEFORE YOU BEGIN</p><h2>A few essentials.</h2><p class="intro">The details that matter.</p></div><div class="faq-list"><details><summary>Who can participate?</summary><p>{E['eligibility']}.</p></details><details><summary>How many people can be on a team?</summary><p>Each team must have 2–4 members.</p></details><details><summary>When and where is the event?</summary><p>Ace Hackathon starts at 10:00 AM IST on 13 November 2026 at ESB Seminar Hall, Ramaiah Institute of Technology.</p></details><details><summary>When does registration close?</summary><p>12 November 2026 at 11:59 PM IST. The official registration link will be added once available.</p></details></div></section>
<section class="section registration" id="registration"><p class="eyebrow">05 / YOUR NEXT CHALLENGE</p><h2>Great ideas start<br>with a little gravity.</h2><p class="tagline">Code. Create. Conquer.</p><dl class="event-facts"><div><dt>WHEN</dt><dd>{E['date']}<br>{E['start']}</dd></div><div><dt>WHERE</dt><dd>{E['venue']}<br>{E['college']}</dd></div><div><dt>WHO</dt><dd>{E['eligibility']}<br>Teams of {E['teamSize']}</dd></div><div><dt>REGISTRATION DEADLINE</dt><dd>12 November 2026<br>11:59 PM IST</dd></div></dl>{f'<a class="button primary" href="{REG}" data-register>Register Now ↗</a>' if E['registrationUrl'] else '<p class="registration-status">Registration link coming soon</p><p class="muted small">The official Google Form will be linked here once available.</p>'}<button class="cosmic-note" id="time-note" aria-expanded="false">τ ≠ t <span id="time-message">A matter of perspective.</span></button></section></main>'''
(ROOT/'index.html').write_text(page('Code. Create. Conquer.',body))

cards=''
for p in P:
 source=p['source'] or 'Contributor to be announced'
 cards+=f'''<article class="problem-card" data-number="{p['id']}" data-domains="{esc('|'.join(p['domains']))}" data-source="{esc(p['source'] or '')}" data-search="{esc((p['id']+' '+p['slug']+' '+p['title']+' '+p['brief']).lower(),quote=True)}"><p class="problem-index">{p['id']}</p><h2>{esc(p['title'])}</h2><p class="source"><span>Source</span>{esc(source)}</p><p class="problem-summary">{esc(p['summary'])}</p><p class="category">{' / '.join(map(esc,p['domains']))}</p><a class="card-link" href="/problem-statements/{p['slug']}/">View Full Problem Statement <span aria-hidden="true">↗</span></a></article>'''
options=''.join(f'<option>{esc(x)}</option>' for x in sorted(set(d for p in P for d in p['domains'])))
sources=sorted(set(p['source'] for p in P if p['source']))
source_filter='<label>Contributor<select id="source"><option value="">All contributors</option>'+''.join(f'<option>{esc(x)}</option>' for x in sources)+'</select></label>' if sources else ''
directory=f'''<main class="directory-main" id="main"><section class="directory-heading container"><a class="back-link" href="/">← Back to Home</a><p class="eyebrow">THE CHALLENGE DIRECTORY</p><div class="directory-title"><h1>Problem<br>Statements<span>.</span></h1><div class="published-count"><strong>{len(P):02d}</strong><span>PUBLISHED BRIEFS</span></div></div><p class="intro">Real-world challenges inspired by leading global companies. Individual contributing organizations have not yet been announced.</p><p class="directory-instructions">Search by title, problem number or keyword. Open a statement to read its full requirements, expected outcomes and demonstration notes.</p><form class="filter-toolbar" role="search" onsubmit="return false"><label class="search-field"><span class="sr-only">Search problem statements</span><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg><input id="search" type="search" placeholder="Search by title, keyword or PS–01" autocomplete="off"></label><label>Category<select id="category"><option value="">All categories</option>{options}</select></label>{source_filter}<button class="reset-button" id="reset" type="reset">Reset filters</button></form><noscript><p class="muted">Search needs JavaScript. All briefs remain available below.</p><style>.filter-toolbar{{display:none}}</style></noscript><p id="result-count" role="status">{len(P)} of {len(P)} problem statements</p></section><section class="container problem-grid" aria-label="Published problem statements">{cards}</section><div class="container empty-state" id="empty" hidden><span aria-hidden="true">∅</span><h2>No matching signals.</h2><p>Try another keyword or reset the filters.</p><button class="button secondary" id="empty-reset">Reset filters</button></div><div class="container directory-end"><a class="back-link" href="/">← Back to Home</a><span class="science-note">A QUIETER CORNER OF THE UNIVERSE.</span></div></main>'''
(ROOT/'problem-statements/index.html').write_text(page('Problem Statements',directory,True))
for p in P:
 destination=ROOT/'problem-statements'/p['slug'];destination.mkdir(exist_ok=True)
 body=f'''<main id="main" class="brief-main"><article class="brief-document"><a class="back-link" href="/problem-statements/">← All Problem Statements</a><p class="problem-index">{p['id']}</p><h1>{esc(p['title'])}</h1><div class="brief-meta"><p><span>SOURCE / CONTRIBUTOR</span>{esc(p['source'] or 'Contributor to be announced')}</p><p><span>CATEGORIES</span>{' / '.join(map(esc,p['domains']))}</p></div><div class="brief-content">{brief_html(p)}</div><div class="brief-end"><a class="button secondary" href="/problem-statements/">← Back to directory</a><a href="/">Back to Home ↗</a></div></article></main>'''
 (destination/'index.html').write_text(page(p['title'],body,True,True))
print(f'Built homepage, directory and {len(P)} complete brief pages.')

credits = '<main id="main" class="brief-main"><article class="brief-document"><a class="back-link" href="/">← Back to Home</a><h1>Visual credits</h1><div class="brief-content"><h2>Earth imagery</h2><p>Earth day texture by <a href="https://www.solarsystemscope.com/textures/">Solar System Scope</a>, licensed under <a href="https://creativecommons.org/licenses/by/4.0/">CC BY 4.0</a>. Resized to 4096 and 2048 pixels for web delivery. The globe, atmosphere and orbital field are rendered live.</p><p>Cloud and normal textures from the <a href="https://github.com/mrdoob/three.js/tree/r180/examples/textures/planets">Three.js example collection</a>.</p><h2>Open-source tools and type</h2><p>Three.js r180, MIT license. Space Grotesk and Inter, SIL Open Font License. Local license copies are included with the project.</p><h2>Brand assets</h2><p>ACE Club, PARTEX, Coastal Naati Kitchen and TAGS marks supplied by the organizer. Other marks were sourced from their official websites with organizer permission. Each mark belongs to its respective owner. Inspiration references are separate from event sponsorships.</p></div></article></main>'
(ROOT/'credits.html').write_text(page('Visual credits', credits, True, True))
